-- Rows a fact-time join admits that were not knowable at prediction time.
-- spark dialect. Generated by tools/emit_sql.py; `make sql` regenerates.
SELECT
    p.entity_id,
    e.event_type,
    COUNT(*) AS unknowable_rows,
    MIN(e.arrival_days - p.prediction_days) AS earliest_arrival_after_days,
    MAX(e.arrival_days - e.fact_days) AS worst_delay_days
FROM predictions AS p
JOIN events AS e
  ON e.entity_id = p.entity_id
 AND e.fact_time > p.prediction_time - INTERVAL 90 DAY
 AND e.fact_time <= p.prediction_time
 AND e.arrival_time > p.prediction_time
GROUP BY p.entity_id, e.event_type
ORDER BY unknowable_rows DESC, p.entity_id, e.event_type
